import json

# Verify transform reproduces demo exactly
def transform(grid):
    """Transformation rule: 9->2 if left=8 AND right=8, else becomes 8."""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if c == 0 or c == cols - 1:
                result[r][c] = 8
            else:
                if grid[r][c] == 9 and grid[r][c-1] == 8 and grid[r][c+1] == 8:
                    result[r][c] = 2
                else:
                    result[r][c] = 8
    return result

